ВЫБРАТЬ
    ВТ_РезультатПредв.ВеличинаИндексации17 КАК ВеличинаИндексации17
ПОМЕСТИТЬ ВТ_258НПО
ИЗ
    ВТ_РезультатПредв КАК ВТ_РезультатПредв;
